#!/usr/bin/env sh
# WHAT: creates the local .env with fresh random secrets for Keycloak (run once).
# WHY:  no secret is committed to the repository; each machine makes its own.
#       Safe to re-run: an existing .env is left untouched.
#
#   sh scripts/setup.sh

set -eu
env_file="$(dirname "$0")/../.env"
if [ -f "$env_file" ]; then
  echo ".env already exists; nothing to do."
  exit 0
fi

secret() { od -An -N32 -tx1 /dev/urandom | tr -d ' \n'; }

cat > "$env_file" <<EOF
# Local secrets for docker compose. Generated by scripts/setup; never commit this file.
EASYTRAVEL_OIDC_SECRET=$(secret)
KEYCLOAK_ADMIN_PASSWORD=$(secret)
EOF
echo "Created .env with new random secrets."
